// Put the config onto each applicant, so the ruleset stays a pure function
// of its input and does not have to reach outside itself for anything.
//
// The items come from the trigger rather than from this node's input,
// because this node's input is the single config row -- the Config node
// replaced the items with its query result, which is what every Postgres
// node does and the most common way to lose data in n8n.
const cfg = $('Config').first().json.config ?? {};

return $('Called per applicant').all().map((item) => ({
  json: { ...item.json, _config: cfg },
}));

